  - destruct (lapi_0RB0LD_1RC1LB_1LD1RC_0RC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC1LB_1LD1RC_0RC1LA B0_0RB0LD_1RC1LB_1LD1RC_0RC1LA B1_0RB0LD_1RC1LB_1LD1RC_0RC1LA 4 21 p j' [] []).
    + exact run_ovf_0RB0LD_1RC1LB_1LD1RC_0RC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1RC1LB_1LD1RC_0RC1LA p j' E).
    + exact (geo_0RB0LD_1RC1LB_1LD1RC_0RC1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1RC1LB_1LD1RC_0RC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 17.
  assert (H : match csteps tm 17 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

