Definition chi_0RB0LD_1RC1LC_0LA0RB_1RB1LA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_0RB0LD_1RC1LC_0LA0RB_1RB1LA : srun tm false true chi_0RB0LD_1RC1LC_0LA0RB_1RB1LA A0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some (A1_0RB0LD_1RC1LC_0LA0RB_1RB1LA, 4, 4).
