(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LD_1RC1LC_0LA0RB_1RB1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB0LD_1RC1LC_0LA0RB_1RB1LA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_0RB0LD_1RC1LC_0LA0RB_1RB1LA : srun tm false true chn_0RB0LD_1RC1LC_0LA0RB_1RB1LA AI0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some (AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA, 4, 4).
