(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB0LD_1RC1LC_0LA0RB_1RB1LA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_0RB0LD_1RC1LC_0LA0RB_1RB1LA : srun tm true true chb_0RB0LD_1RC1LC_0LA0RB_1RB1LA B0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some (BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LD_1RC1LC_0LA0RB_1RB1LA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 7; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB0LD_1RC1LC_0LA0RB_1RB1LA : srun tm true true che_0RB0LD_1RC1LC_0LA0RB_1RB1LA BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some (B1_0RB0LD_1RC1LC_0LA0RB_1RB1LA, 4, 10).
