  unfold Cin_0RB0LD_1RC1LC_0LA0RB_1RB1LA, cden, AI0_0RB0LD_1RC1LC_0LA0RB_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LD_1RC1LC_0LA0RB_1RB1LA, cden, AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA).
  split; [lia|]. split; [| exact (gen_0RB0LD_1RC1LC_0LA0RB_1RB1LA v i q0 E)].
  rewrite (gsn_0RB0LD_1RC1LC_0LA0RB_1RB1LA v i q0 E).
  exact (srun_sound tm false true chn_0RB0LD_1RC1LC_0LA0RB_1RB1LA AI0_0RB0LD_1RC1LC_0LA0RB_1RB1LA AI1_0RB0LD_1RC1LC_0LA0RB_1RB1LA 4 4
           run_inner_0RB0LD_1RC1LC_0LA0RB_1RB1LA (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall j, lift (cden [] [] j BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA = (StC, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LD_1RC1LC_0LA0RB_1RB1LA. rewrite epow2_0RB0LD_1RC1LC_0LA0RB_1RB1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LD_1RC1LC_0LA0RB_1RB1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LD_1RC1LC_0LA0RB_1RB1LA, cden, BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LD_1RC1LC_0LA0RB_1RB1LA p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA).
    split; [lia|]. split; [| exact (gbo_0RB0LD_1RC1LC_0LA0RB_1RB1LA j)].
    rewrite (gso_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j E).
    exact (srun_sound tm true true chb_0RB0LD_1RC1LC_0LA0RB_1RB1LA B0_0RB0LD_1RC1LC_0LA0RB_1RB1LA BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA 4 4
             run_boot_0RB0LD_1RC1LC_0LA0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_0RB0LD_1RC1LC_0LA0RB_1RB1LA).
    split; [| exact (geo_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j E)].
    rewrite (gxi_0RB0LD_1RC1LC_0LA0RB_1RB1LA j).
    exact (srun_sound tm true true che_0RB0LD_1RC1LC_0LA0RB_1RB1LA BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA B1_0RB0LD_1RC1LC_0LA0RB_1RB1LA 4 10
             run_exit_0RB0LD_1RC1LC_0LA0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1RC1LC_0LA0RB_1RB1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LD_1RC1LC_0LA0RB_1RB1LA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA). split;
      [| exact (gbo_0RB0LD_1RC1LC_0LA0RB_1RB1LA j)].
    rewrite (gso_0RB0LD_1RC1LC_0LA0RB_1RB1LA p j E).
    exact (srun_sound tm true true chb_0RB0LD_1RC1LC_0LA0RB_1RB1LA B0_0RB0LD_1RC1LC_0LA0RB_1RB1LA BB1_0RB0LD_1RC1LC_0LA0RB_1RB1LA 4 4
             run_boot_0RB0LD_1RC1LC_0LA0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LD_1RC1LC_0LA0RB_1RB1LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LD_1RC1LC_0LA0RB_1RB1LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LD_1RC1LC_0LA0RB_1RB1LA : forall t, ~ In t pins_0RB0LD_1RC1LC_0LA0RB_1RB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LD_1RC1LC_0LA0RB_1RB1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_1RC1LC_0LA0RB_1RB1LA (StA, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_1RC1LC_0LA0RB_1RB1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1RC1LC_0LA0RB_1RB1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LD_1RC1LC_0LA0RB_1RB1LA
