Lemma fire_0RB0LD_1RC1RA_0LA0RB_1RB1LA : forall t, ~ In t pins_0RB0LD_1RC1RA_0LA0RB_1RB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
