  split; [lia|]. split; [| exact (gen_0RB0LD_1RC1RA_1LD0RB_0RC1LC v i q0 E)].
  rewrite (gsn_0RB0LD_1RC1RA_1LD0RB_0RC1LC v i q0 E).
  exact (srun_sound tm false true chn_0RB0LD_1RC1RA_1LD0RB_0RC1LC AI0_0RB0LD_1RC1RA_1LD0RB_0RC1LC AI1_0RB0LD_1RC1RA_1LD0RB_0RC1LC 4 6
           run_inner_0RB0LD_1RC1RA_1LD0RB_0RC1LC (Jp q0 ++ []) [] i
