(** ** The lap *)

Lemma lap_0RB0LD_1RC1RA_1LD0RB_0RC1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
