Lemma fireo_0RB0LD_1RC1RA_1LD0RB_0RC1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1RC1RA_1LD0RB_0RC1LC = Some t ->
