  apply (fire_via_fill tm Cc Cin lapin_0RB0LD_1RC1RA_1LD0RB_0RC1LC t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_0RB0LD_1RC1RA_1LD0RB_0RC1LC). split;
      [| exact (gbo_0RB0LD_1RC1RA_1LD0RB_0RC1LC j)].
