    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_1RC1RA_1LD0RB_0RC1LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_1RC1RA_1LD0RB_0RC1LC [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1RC1RA_1LD0RB_0RC1LC [SWinR 2; SRotL 1; SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
