    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LD_1RC1RB_1LC1LA____0LA Z0_0RB0LD_1RC1RB_1LC1LA____0LA Z1_0RB0LD_1RC1RB_1LC1LA____0LA 0 4
               run_z_0RB0LD_1RC1RB_1LC1LA____0LA (Dp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LD_1RC1RB_1LC1LA____0LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LD_1RC1RB_1LC1LA____0LA P0_0RB0LD_1RC1RB_1LC1LA____0LA P1_0RB0LD_1RC1RB_1LC1LA____0LA 4 8
