(** ** The lap *)

Lemma lap_0RB0LD_1RC1RB_1LD1RC_0LA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
