  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1RC1RB_1LD1RC_0LA1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LD_1RC1RB_1LD1RC_0LA1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1RC1RB_1LD1RC_0LA1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
