Lemma gsi_0RB0LD_1RC1RB_1LD1RC_0RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB0LD_1RC1RB_1LD1RC_0RB1LA.
Proof.
