Lemma gen_0RB0LD_1RC1RB_1LD1RC_0RC1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LD_1RC1RB_1LD1RC_0RC1LA) = lift (Cin (Pos.succ v)).
