    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  4*j+20 steps
      overflow  (cview p = (S j, None)):   boot 4*j+11, then the inner counter's own laps to the
                                           all-ones fill, then exit 4*j+30

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_01_11_011 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift ILCounter.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_0RB0LD_1RC1RB_1LD1RC_1RC1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LD_1RC1RB_1LD1RC_1RC1LA.

(** 0RB0LD_1RC1RB_1LD1RC_1RC1LA *)
(** 0RB0LD_1RC1RB_1LD1RC_1RC1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LD_1RC1RB_1LD1RC_1RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB0RD_1LC1LB_1RD1LC_1LC1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LD_1RC1RB_1LD1RC_1RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_1RC1RB_1LD1RC_1RC1LA : list Instr := [].
Definition tmw_0RB0LD_1RC1RB_1LD1RC_1RC1LA : TM := tm_wrap_trs tmm_0RB0LD_1RC1RB_1LD1RC_1RC1LA pins_0RB0LD_1RC1RB_1LD1RC_1RC1LA.
Local Notation tm := tmw_0RB0LD_1RC1RB_1LD1RC_1RC1LA.

Lemma mirror_ok_0RB0LD_1RC1RB_1LD1RC_1RC1LA : mirror_tm tm_0RB0LD_1RC1RB_1LD1RC_1RC1LA = tmm_0RB0LD_1RC1RB_1LD1RC_1RC1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA (p : positive) : cconf := (StC, (Ap_Alph_01_11_011 p ++ [S0], S1, [S1;S1;S1;S1])).
Local Notation Cc := Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA.

(** ** The certificate *)

Definition A0_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S0;S1]) S1 (mkS [S1;S1;S1;S1] [] 0 0 []).
Definition A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S0;S1] 1 0 [S1;S1]) S1 (mkS [S1;S1;S1;S1;S0] [] 0 0 []).
Definition chi_0RB0LD_1RC1RB_1LD1RC_1RC1LA : list lstep := [SCycL 2 0; SWin 2; SCycR 2; SWin 4; SWinR 14].

Lemma run_int_0RB0LD_1RC1RB_1LD1RC_1RC1LA : srun tm false true chi_0RB0LD_1RC1RB_1LD1RC_1RC1LA A0_0RB0LD_1RC1RB_1LD1RC_1RC1LA = Some (A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA, 4, 20).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S0;S1;S1;S0]) S1 (mkS [S1;S1;S1;S1] [] 0 0 []).
Definition B1_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S0;S1] 1 1 [S0;S1;S1]) S1 (mkS [S1;S1;S1;S1;S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StC *)
Definition Cin_0RB0LD_1RC1RB_1LD1RC_1RC1LA (v : positive) : cconf := (StC, (Ip v ++ [S1;S1;S1], S0, [S1;S1;S1])).
Local Notation Cin := Cin_0RB0LD_1RC1RB_1LD1RC_1RC1LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S1;S1] [] 0 0 []).
Definition AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S1;S1;S0] [] 0 0 []).
Definition chn_0RB0LD_1RC1RB_1LD1RC_1RC1LA : list lstep := [SWin 3; SWinR 5; SCycL 2 0; SWin 4; SCycR 2; SWin 8].

Lemma run_inner_0RB0LD_1RC1RB_1LD1RC_1RC1LA : srun tm false true chn_0RB0LD_1RC1RB_1LD1RC_1RC1LA AI0_0RB0LD_1RC1RB_1LD1RC_1RC1LA = Some (AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA, 4, 20).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S1;S1;S0]) S0 (mkS [S1;S1;S1;S0] [] 0 0 []).
Definition chb_0RB0LD_1RC1RB_1LD1RC_1RC1LA : list lstep := [SCycL 2 0; SWin 2; SCycR 2; SWin 4; SWinR 5; SUnrotL 1].

Lemma run_boot_0RB0LD_1RC1RB_1LD1RC_1RC1LA : srun tm true true chb_0RB0LD_1RC1RB_1LD1RC_1RC1LA B0_0RB0LD_1RC1RB_1LD1RC_1RC1LA = Some (BB1_0RB0LD_1RC1RB_1LD1RC_1RC1LA, 4, 11).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LD_1RC1RB_1LD1RC_1RC1LA : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1;S1;S1]) S0 (mkS [S1;S1;S1] [] 0 0 []).
Definition che_0RB0LD_1RC1RB_1LD1RC_1RC1LA : list lstep := [SWin 3; SWinR 5; SCycL 2 0; SWin 4; SWinL 6; SCycR 2; SWin 6; SWinR 6; SRotL 2; SFoldL 1].

Lemma run_exit_0RB0LD_1RC1RB_1LD1RC_1RC1LA : srun tm true true che_0RB0LD_1RC1RB_1LD1RC_1RC1LA BE0_0RB0LD_1RC1RB_1LD1RC_1RC1LA = Some (B1_0RB0LD_1RC1RB_1LD1RC_1RC1LA, 4, 30).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_01_11_011 q0 ++ [S0]) [] j A0_0RB0LD_1RC1RB_1LD1RC_1RC1LA.
Proof.
  intros p j q0 E. destruct (Alph_01_11_011.cview_some_Alph_01_11_011 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA, cden, A0_0RB0LD_1RC1RB_1LD1RC_1RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S1;S1;S0] where the anchor has [S1;S1;S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_01_11_011 q0 ++ [S0]) [] j A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_01_11_011.cview_some_Alph_01_11_011 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA, cden, A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S1;S1;S0]) with (([S1;S1;S1;S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 20), (cden (Ap_Alph_01_11_011 q0 ++ [S0]) [] j A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA).
  split; [lia|]. split; [| exact (gei_0RB0LD_1RC1RB_1LD1RC_1RC1LA p j q0 E)].
  rewrite (gsi_0RB0LD_1RC1RB_1LD1RC_1RC1LA p j q0 E).
  exact (srun_sound tm false true chi_0RB0LD_1RC1RB_1LD1RC_1RC1LA A0_0RB0LD_1RC1RB_1LD1RC_1RC1LA A1_0RB0LD_1RC1RB_1LD1RC_1RC1LA 4 20
           run_int_0RB0LD_1RC1RB_1LD1RC_1RC1LA (Ap_Alph_01_11_011 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LD_1RC1RB_1LD1RC_1RC1LA.
Proof.
  intros p j E. destruct (Alph_01_11_011.cview_none_Alph_01_11_011 p j E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA, cden, B0_0RB0LD_1RC1RB_1LD1RC_1RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC1RB_1LD1RC_1RC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_01_11_011.cview_none_Alph_01_11_011 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1RC1RB_1LD1RC_1RC1LA
             = (StC, (rep [S0;S1] (S j) ++ [S0;S1;S1], S1, ([S1;S1;S1;S1]) ++ [S0]))).
  { unfold cden, B1_0RB0LD_1RC1RB_1LD1RC_1RC1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S1] (S j) ++ [S0;S1;S1]) ++ [S0], S1, [S1;S1;S1;S1]))).
  { unfold Cc_0RB0LD_1RC1RB_1LD1RC_1RC1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB0LD_1RC1RB_1LD1RC_1RC1LA. reflexivity.
Qed.

Lemma gsn_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1;S1;S1]) [] i AI0_0RB0LD_1RC1RB_1LD1RC_1RC1LA.
