  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1;S1;S1]) [] i AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LD_1RC1RB_1LD1RC_1RC1LA, cden, AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S1;S0]) with (([S1;S1;S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LD_1RC1RB_1LD1RC_1RC1LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 20), (cden (Ip q0 ++ [S1;S1;S1]) [] i AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA).
  split; [lia|]. split; [| exact (gen_0RB0LD_1RC1RB_1LD1RC_1RC1LA v i q0 E)].
  rewrite (gsn_0RB0LD_1RC1RB_1LD1RC_1RC1LA v i q0 E).
  exact (srun_sound tm false true chn_0RB0LD_1RC1RB_1LD1RC_1RC1LA AI0_0RB0LD_1RC1RB_1LD1RC_1RC1LA AI1_0RB0LD_1RC1RB_1LD1RC_1RC1LA 4 20
           run_inner_0RB0LD_1RC1RB_1LD1RC_1RC1LA (Ip q0 ++ [S1;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
