(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LD_1RC1RC_1LD0RC_1RB0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] 0 Z0_0RB0LD_1RC1RC_1LD0RC_1RB0LA /\
  cden (Bp q0 ++ [S0]) [] 0 Z1_0RB0LD_1RC1RC_1LD0RC_1RB0LA = Cc (Pos.succ p).
