  unfold Cc_0RB0LD_1RC1RC_1LD0RC_1RB0LA, cden, Z0_0RB0LD_1RC1RC_1LD0RC_1RB0LA, Z1_0RB0LD_1RC1RC_1LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LD_1RC1RC_1LD0RC_1RB0LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j P0_0RB0LD_1RC1RC_1LD0RC_1RB0LA /\
  cden (Bp q0 ++ [S0]) [] j P1_0RB0LD_1RC1RC_1LD0RC_1RB0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (BpCounter.cview_some_B p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LD_1RC1RC_1LD0RC_1RB0LA, cden, P0_0RB0LD_1RC1RC_1LD0RC_1RB0LA, P1_0RB0LD_1RC1RC_1LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
