    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LD_1RC1RC_1LD0RC_1RB0LA Z0_0RB0LD_1RC1RC_1LD0RC_1RB0LA Z1_0RB0LD_1RC1RC_1LD0RC_1RB0LA 0 4
               run_z_0RB0LD_1RC1RC_1LD0RC_1RB0LA (Bp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LD_1RC1RC_1LD0RC_1RB0LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LD_1RC1RC_1LD0RC_1RB0LA P0_0RB0LD_1RC1RC_1LD0RC_1RB0LA P1_0RB0LD_1RC1RC_1LD0RC_1RB0LA 6 10
