(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_0000_0100_01 q0 ++ [S0]) [] j A0_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
Proof.
  intros p j q0 E. destruct (Alph_0000_0100_01.cview_some_Alph_0000_0100_01 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1RD_1LD0RC_1RB0LA, cden, A0_0RB0LD_1RC1RD_1LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1;S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_0000_0100_01 q0 ++ [S0]) [] j A1_0RB0LD_1RC1RD_1LD0RC_1RB0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_0000_0100_01.cview_some_Alph_0000_0100_01 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LD_1RC1RD_1LD0RC_1RB0LA, cden, A1_0RB0LD_1RC1RD_1LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (10 * j + 4). split; [lia|].
  rewrite (gsi_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0LD_1RC1RD_1LD0RC_1RB0LA A0_0RB0LD_1RC1RD_1LD0RC_1RB0LA A1_0RB0LD_1RC1RD_1LD0RC_1RB0LA 10 4
             run_int_0RB0LD_1RC1RD_1LD0RC_1RB0LA (Ap_Alph_0000_0100_01 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j q0 E).
Qed.

Lemma gso_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
Proof.
  intros p j E. destruct (Alph_0000_0100_01.cview_none_Alph_0000_0100_01 p j E) as (H1 & _).
  unfold Cc_0RB0LD_1RC1RD_1LD0RC_1RB0LA, cden, B0_0RB0LD_1RC1RD_1LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC1RD_1LD0RC_1RB0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_0000_0100_01.cview_none_Alph_0000_0100_01 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1RC1RD_1LD0RC_1RB0LA
             = (StA, (rep [S0;S0;S0;S0] (S j) ++ [S0;S1], S0, []))).
  { unfold cden, B1_0RB0LD_1RC1RD_1LD0RC_1RB0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S0;S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LD_1RC1RD_1LD0RC_1RB0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LD_1RC1RD_1LD0RC_1RB0LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC1RD_1LD0RC_1RB0LA B0_0RB0LD_1RC1RD_1LD0RC_1RB0LA B1_0RB0LD_1RC1RD_1LD0RC_1RB0LA 10 14 p j' [] []).
    + exact run_ovf_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j' E).
    + exact (geo_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LD_1RC1RD_1LD0RC_1RB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1RC1RD_1LD0RC_1RB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LD_1RC1RD_1LD0RC_1RB0LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LD_1RC1RD_1LD0RC_1RB0LA : forall t, ~ In t pins_0RB0LD_1RC1RD_1LD0RC_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 4; SWinL 5]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LD_1RC1RD_1LD0RC_1RB0LA
      with (l := [SRotL 1; SWin 1; SCycL 6 0; SWin 4; SWinL 4]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_0RB0LD_1RC1RD_1LD0RC_1RB0LA : NeverQuasiHaltsTr tmm_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
Proof.
  apply (glue_neverqhtr tmm_0RB0LD_1RC1RD_1LD0RC_1RB0LA pins_0RB0LD_1RC1RD_1LD0RC_1RB0LA Cc 1).
  - exact boot_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
  - intros p _. apply lap_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
  - intros t Ht p _. apply fire_0RB0LD_1RC1RD_1LD0RC_1RB0LA. exact Ht.
Qed.

Theorem nqhtr_0RB0LD_1RC1RD_1LD0RC_1RB0LA : NeverQuasiHaltsTr tm_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
Proof. apply (neverqhtr_mirror tm_0RB0LD_1RC1RD_1LD0RC_1RB0LA). rewrite mirror_ok_0RB0LD_1RC1RD_1LD0RC_1RB0LA. exact nqhtrm_0RB0LD_1RC1RD_1LD0RC_1RB0LA. Qed.

Theorem nonhalt_0RB0LD_1RC1RD_1LD0RC_1RB0LA : NonHalt tm_0RB0LD_1RC1RD_1LD0RC_1RB0LA.
Proof. apply never_qh_tr_nonhalt, nqhtr_0RB0LD_1RC1RD_1LD0RC_1RB0LA. Qed.

