(** ** The lap *)

Lemma lap_0RB0RB_0LC1RA_1RB1LD_1LA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RB_0LC1RA_1RB1LD_1LA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0RB_0LC1RA_1RB1LD_1LA1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0RB_0LC1RA_1RB1LD_1LA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 10.
  assert (H : match csteps tm 10 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RB_0LC1RA_1RB1LD_1LA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0RB_0LC1RA_1RB1LD_1LA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RB_0LC1RA_1RB1LD_1LA1LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0RB_0LC1RA_1RB1LD_1LA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0RB_0LC1RA_1RB1LD_1LA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0RB_0LC1RA_1RB1LD_1LA1LC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB0RB_0LC1RA_1RB1LD_1LA1LC). split;
      [| exact (gbo_0RB0RB_0LC1RA_1RB1LD_1LA1LC j)].
    rewrite (gso_0RB0RB_0LC1RA_1RB1LD_1LA1LC p j E).
    exact (srun_sound tm true true chb_0RB0RB_0LC1RA_1RB1LD_1LA1LC B0_0RB0RB_0LC1RA_1RB1LD_1LA1LC BB1_0RB0RB_0LC1RA_1RB1LD_1LA1LC 4 8
             run_boot_0RB0RB_0LC1RA_1RB1LD_1LA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0RB_0LC1RA_1RB1LD_1LA1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0RB_0LC1RA_1RB1LD_1LA1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RB_0LC1RA_1RB1LD_1LA1LC : forall t, ~ In t pins_0RB0RB_0LC1RA_1RB1LD_1LA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0RB_0LC1RA_1RB1LD_1LA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0RB_0LC1RA_1RB1LD_1LA1LC (StA, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2; SCycL 2 0; SWin 2; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2; SCycL 2 0; SWin 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2; SCycL 2 0; SWin 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0RB_0LC1RA_1RB1LD_1LA1LC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2; SCycL 2 0; SWin 2; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RA_1RB1LD_1LA1LC [SWinR 2; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_0RB0RB_0LC1RA_1RB1LD_1LA1LC : NeverQuasiHaltsTr tm_0RB0RB_0LC1RA_1RB1LD_1LA1LC.
