Lemma lapo_0RB0RB_0LC1RD_1RB1LC_0LA1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0RB_0LC1RD_1RB1LC_0LA1RA p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB0RB_0LC1RD_1RB1LC_0LA1RA).
