    intros p1 j1 E1.
    exact (firex_0RB0RB_0LC1RD_1RB1LC_0LA1RA [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_0RB0RB_0LC1RD_1RB1LC_0LA1RA : NeverQuasiHaltsTr tm_0RB0RB_0LC1RD_1RB1LC_0LA1RA.
Proof.
  apply (glue_neverqhtr tm_0RB0RB_0LC1RD_1RB1LC_0LA1RA pins_0RB0RB_0LC1RD_1RB1LC_0LA1RA Cc 1).
