Lemma geo_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RB_0LC1RD_1RB1LC_1RB1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0RB_0LC1RD_1RB1LC_1RB1RA
             = (StC, (rep [S1;S1;S0] (S j) ++ [S1;S1;S1], S1, ([S1;S1;S1]) ++ [S0]))).
  { unfold cden, B1_0RB0RB_0LC1RD_1RB1LC_1RB1RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1;S0] (S j) ++ [S1;S1;S1]) ++ [S0], S1, [S1;S1;S1]))).
  { unfold Cc_0RB0RB_0LC1RD_1RB1LC_1RB1RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
