(** ** The lap *)

Lemma lap_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RB_0LC1RD_1RB1LC_1RB1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0RB_0LC1RD_1RB1LC_1RB1RA B0_0RB0RB_0LC1RD_1RB1LC_1RB1RA B1_0RB0RB_0LC1RD_1RB1LC_1RB1RA 6 26 p j' [] []).
    + exact run_ovf_0RB0RB_0LC1RD_1RB1LC_1RB1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0RB_0LC1RD_1RB1LC_1RB1RA p j' E).
    + exact (geo_0RB0RB_0LC1RD_1RB1LC_1RB1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0RB_0LC1RD_1RB1LC_1RB1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 42.
  assert (H : match csteps tm 42 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 42 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RB_0LC1RD_1RB1LC_1RB1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0RB_0LC1RD_1RB1LC_1RB1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RB_0LC1RD_1RB1LC_1RB1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RB_0LC1RD_1RB1LC_1RB1RA : forall t, ~ In t pins_0RB0RB_0LC1RD_1RB1LC_1RB1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0RB_0LC1RD_1RB1LC_1RB1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 8] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 7] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 5] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 4] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 8; SCycR 3; SWin 3; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RB_0LC1RD_1RB1LC_1RB1RA [SCycL 3 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_0RB0RB_0LC1RD_1RB1LC_1RB1RA : NeverQuasiHaltsTr tm_0RB0RB_0LC1RD_1RB1LC_1RB1RA.
