Lemma geo_0RB0RB_1LA1RC_0LD1RA_1RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RB_1LA1RC_0LD1RA_1RB1LD) = lift (Cc (Pos.succ p)).
