(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RB_1RC1RC_0LD1RA_1RB1LD : forall t, ~ In t pins_0RB0RB_1RC1RC_0LD1RA_1RB1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0RB_1RC1RC_0LD1RA_1RB1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0RB_1RC1RC_0LD1RA_1RB1LD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0RB_1RC1RC_0LD1RA_1RB1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 6; SCycR 3; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0RB_1RC1RC_0LD1RA_1RB1LD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0RB_1RC1RC_0LD1RA_1RB1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0RB_1RC1RC_0LD1RA_1RB1LD (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0RB_1RC1RC_0LD1RA_1RB1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 6; SCycR 3; SWin 1; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0RB_1RC1RC_0LD1RA_1RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0RB_1RC1RC_0LD1RA_1RB1LD
      with (l := []).
