    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0RB_1RC1RC_0LD1RA_1RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0RB_1RC1RC_0LD1RA_1RB1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_0RB0RB_1RC1RC_0LD1RA_1RB1LD : NeverQuasiHaltsTr tm_0RB0RB_1RC1RC_0LD1RA_1RB1LD.
Proof.
  apply (glue_neverqhtr tm_0RB0RB_1RC1RC_0LD1RA_1RB1LD pins_0RB0RB_1RC1RC_0LD1RA_1RB1LD Cc 1).
